 static FileStream Lock(string root){Directory.CreateDirectory(root);var timer=System.Diagnostics.Stopwatch.StartNew();while(true){try{return new FileStream(Path.Combine(root,"store.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}catch(IOException){if(timer.ElapsedMilliseconds>5000)throw new IOException("Projection store busy; retry explicitly");Thread.Sleep(10);}}}
