  if(operation=="projectionQueue"){
   string queueRoot=Path.Combine(Path.GetDirectoryName(project)!,".confectory","editor-projections");using var queueLock=Lock(queueRoot);string queuePath=Path.Combine(queueRoot,"maintenance.json");var queue=File.Exists(queuePath)?JsonNode.Parse(File.ReadAllText(queuePath))!.AsObject():new JsonObject{["schema"]=1,["owners"]=new JsonObject()};string queueOwner=HashText(request["participant"]!.ToString()+"\n"+request["context"]!.ToString());var owners=queue["owners"]!.AsObject();var entries=owners[queueOwner] as JsonObject??new JsonObject();string action=request["action"]!.GetValue<string>();if(action=="list")return new JsonArray(entries.Select(x=>x.Value!.DeepClone()).ToArray());if(owners.Count>=64&&owners[queueOwner] is null)throw new InvalidOperationException("Maintenance owner capacity reached");bool changed=false;
