  }
  if(operation=="editorDescribe"){var element=registry.Effective(request["element"]!.GetValue<string>());var result=AlgorithmProjectionOperations.Editor(element);result["version"]=Hash(File.ReadAllBytes(element.Loc.File));var origins=new JsonObject();foreach(var value in element.Values.Where(x=>x.Key.StartsWith("editor",StringComparison.Ordinal))){string origin=value.Value.Origin;var schema=registry.Get(origin);origins[value.Key]=new JsonObject{["schema"]=origin,["revision"]=Hash(File.ReadAllBytes(schema.Loc.File))};}result["schemaOrigins"]=origins;return result;}
  if(operation=="projectionAffected"){var selected=request["changedIDs"]!.AsArray().Select(x=>x!.ToString()).ToHashSet(StringComparer.Ordinal);if(selected.Count>256)throw new ArgumentException("Bounded changed IDs required");string directory=Path.Combine(Path.GetDirectoryName(project)!,".confectory","editor-projections");var found=new JsonArray();var seen=new HashSet<string>(StringComparer.Ordinal);var known=new HashSet<string>(StringComparer.Ordinal);if(Directory.Exists(directory))foreach(string file in Directory.EnumerateFiles(directory,"*.json")){if(file.EndsWith(".history.json",StringComparison.Ordinal)||Path.GetFileName(file)=="maintenance.json")continue;var record=JsonNode.Parse(File.ReadAllText(file))!;if(record["dependencies"] is not JsonArray dependencies||!dependencies.Any(id=>selected.Contains(id!.ToString())))continue;foreach(var dependency in dependencies)known.Add(dependency!.ToString());string affectedKey=record["function"]+"|"+record["provider"]+"|"+record["target"];if(seen.Add(affectedKey))found.Add(new JsonObject{["function"]=record["function"]!.DeepClone(),["implementation"]=record["provider"]!.DeepClone(),["bodyID"]=record["target"]!.DeepClone()});}return new JsonObject{["affected"]=found,["unknownIDs"]=new JsonArray(selected.Where(id=>!known.Contains(id)).Select(id=>(JsonNode?)JsonValue.Create(id)).ToArray()),["scope"]="stored projection dependency index only; no whole-project source scan"};}
  if(operation=="projectionVersions"){string f=request["function"]!.ToString(),i=request["implementation"]!.ToString(),t=request["target"]!.ToString();string stem=HashText(f+"\n"+i+"\n"+t),directory=Path.Combine(Path.GetDirectoryName(project)!,".confectory","editor-projections"),draftOwner=HashText(request["participant"]!.ToString()+"\n"+request["context"]!.ToString());using var versionLock=Lock(directory);long Version(string owner){string file=Path.Combine(directory,stem+"."+owner+".json");return File.Exists(file)?JsonNode.Parse(File.ReadAllText(file))!["version"]!.GetValue<long>():0;}return new JsonObject{["confirmed"]=Version("source"),["draft"]=Version(draftOwner)};}
