  string function=request["function"]!.GetValue<string>(),implementation=request["implementation"]!.GetValue<string>(),target=request["target"]!.GetValue<string>();if(!function.Contains("::",StringComparison.Ordinal)||!implementation.Contains("::",StringComparison.Ordinal)||!target.StartsWith(implementation+"/body:",StringComparison.Ordinal))throw new ArgumentException("Qualified function/implementation/body-target IDs required");
