  string root=Path.Combine(Path.GetDirectoryName(project)!,".confectory","editor-projections"),key=HashText(function+"\n"+implementation+"\n"+target);string channel=request["channel"]?.ToString()??"confirmed";if(channel!="confirmed"&&channel!="draft")throw new ArgumentException("Explicit confirmed/draft channel required");string owner=channel=="draft"?HashText(request["participant"]!.ToString()+"\n"+request["context"]!.ToString()):"source";string path=Path.Combine(root,key+"."+owner+".json");using var held=Lock(root);foreach(var item in paths){raw[item.Key]=Hash(File.ReadAllBytes(item.Value));content[item.Key]=HashText(File.ReadAllText(item.Value));}JsonObject? previous=File.Exists(path)?JsonNode.Parse(File.ReadAllText(path))!.AsObject():null;
  void Trace(){string? trace=Environment.GetEnvironmentVariable("CONFECTORY_PROJECTION_TRACE");if(trace is not null)File.AppendAllText(trace,new JsonObject{["operation"]=operation,["registryReads"]=new JsonArray(statistics.ReadDocuments.Select(p=>(JsonNode?)JsonValue.Create(p)).ToArray()),["serviceDigestReads"]=new JsonArray(paths.Values.Select(p=>(JsonNode?)JsonValue.Create(p)).ToArray()),["artifact"]=path,["returnedRawSource"]=false}.ToJsonString()+"\n");}
  if(operation=="projectionPublish"){
   var artifact=request["artifact"]!.DeepClone().AsObject();var expected=request["sourceHashes"]!.AsObject();if(artifact["schema"]!.GetValue<int>()!=2||artifact["function"]!.ToString()!=function||artifact["provider"]!.ToString()!=implementation)throw new ArgumentException("Source-free projection schema/identity mismatch");
   string contractText=request["publicContract"]?.GetValue<string>()??File.ReadAllText(paths["contract"]);var publicContract=new Parser(contractText,"<public-contract>").ParseElement();if(HashText(contractText)!=artifact["contractHash"]!.ToString()||publicContract.Id!=function||publicContract.Description!=artifact["description"]!.ToString()||JsonNode.DeepEquals(System.Text.Json.JsonSerializer.SerializeToNode(publicContract.Signature),artifact["signature"])==false)throw new ArgumentException("Public description/signature is not bound to the declared contract revision");
   foreach(var item in raw.Where(item=>item.Key is "contract" or "implementation" or "body"))if(expected[item.Key]?.ToString()!=item.Value!.ToString()){Trace();return new JsonObject{["accepted"]=false,["reason"]="source-revision-raced",["previousVersion"]=previous?["version"]?.DeepClone()};}
   if(request["expectedVersion"] is not null&&request["expectedVersion"]!.GetValue<long>()!=(previous?["version"]?.GetValue<long>()??0)){Trace();return new JsonObject{["accepted"]=false,["reason"]="artifact-version-raced"};}
   if(!File.Exists(path)&&Directory.EnumerateFiles(root,"*.json").Count(f=>!f.EndsWith(".history.json",StringComparison.Ordinal)&&Path.GetFileName(f)!="maintenance.json")>=512)throw new InvalidOperationException("Projection capacity reached; explicit retention required");
