   CheckTree(artifact["tree"]!);var allowed=new HashSet<string>{"schema","function","provider","description","signature","imports","bodyHash","contractHash","implementationHash","status","validation","diagnostics","tree","claims","unknowns","effects","editor","bodyRevision","contractRevision","implementationRevision","bodyID","implementation","analysisMetrics"};foreach(string property in artifact.Select(x=>x.Key))if(!allowed.Contains(property))throw new ArgumentException("Unknown public artifact property");
   bool sourceCurrent=content["body"]!.ToString()==artifact["bodyHash"]!.ToString()&&content["contract"]!.ToString()==artifact["contractHash"]!.ToString()&&content["implementation"]!.ToString()==artifact["implementationHash"]!.ToString();if(channel=="confirmed"&&!sourceCurrent)return new JsonObject{["accepted"]=false,["reason"]="draft-cannot-publish-to-confirmed-channel"};artifact["editor"]=AlgorithmProjectionOperations.Editor(contract);artifact["target"]=target;artifact["channel"]=channel;artifact["owner"]=owner;artifact["sourceHashes"]=raw;artifact["dependencies"]=new JsonArray(function,implementation,target);foreach(string origin in contract.Values.Values.Select(v=>v.Origin).Distinct(StringComparer.Ordinal))if(!artifact["dependencies"]!.AsArray().Any(id=>id!.ToString()==origin))artifact["dependencies"]!.AsArray().Add(origin);artifact["claims"]=new JsonObject{["level"]="syntactic-outline",["semanticReview"]="not-performed",["behaviorValidated"]=false};artifact["version"]=(previous?["version"]?.GetValue<long>()??0)+1;artifact["project"]=registry.Project.Namespace;artifact["semanticReview"]="not-performed";string text=artifact.ToJsonString();if(Encoding.UTF8.GetByteCount(text)>8388608)throw new ArgumentException("Projection artifact capacity exceeded");string temporary=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temporary,text,new UTF8Encoding(false));string historyPath=path+".history.json";var history=File.Exists(historyPath)?JsonNode.Parse(File.ReadAllText(historyPath))!.AsArray():new JsonArray();history.Add(artifact.DeepClone());while(history.Count>8)history.RemoveAt(0);string historyTemporary=historyPath+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(historyTemporary,history.ToJsonString(),new UTF8Encoding(false));File.Move(historyTemporary,historyPath,true);}finally{if(File.Exists(historyTemporary))File.Delete(historyTemporary);}File.Move(temporary,path,true);}finally{if(File.Exists(temporary))File.Delete(temporary);}Trace(