  bool schemasCurrent=raw.Where(item=>item.Key.StartsWith("schema:",StringComparison.Ordinal)).All(item=>previous["sourceHashes"]?[item.Key]?.ToString()==item.Value!.ToString());bool current=schemasCurrent&&content["body"]!.ToString()==previous["bodyHash"]!.ToString()&&content["contract"]!.ToString()==previous["contractHash"]!.ToString()&&content["implementation"]!.ToString()==previous["implementationHash"]!.ToString();bool baseline=raw.All(item=>previous["sourceHashes"]?[item.Key]?.ToString()==item.Value!.ToString());previous["freshness"]=current?"current-source":baseline?"draft-unconfirmed":"stale-source";previous["status"]=previous["diagnostics"]!.AsArray().Count>0?"invalid-syntax":current?"current-unreviewed":baseline?"draft-unconfirmed":"stale";previous["behaviorValidated"]=false;return previous;
